CREATE TABLE public.hackathons (
  id uuid PRIMARY KEY, organizer_id uuid REFERENCES public.profiles(id), type text
)

CREATE POLICY hackathon_announcements_insert ON public.hackathon_announcements FOR INSERT TO authenticated WITH CHECK(
 EXISTS(SELECT 1 FROM public.hackathons h WHERE h.id=hackathon_announcements.hackathon_id AND h.organizer_id=auth.uid())
)

CREATE POLICY hackathon_announcements_update ON public.hackathon_announcements FOR UPDATE TO authenticated USING(
 EXISTS(SELECT 1 FROM public.hackathons h WHERE h.id=hackathon_announcements.hackathon_id AND h.organizer_id=auth.uid())
) WITH CHECK(
 EXISTS(SELECT 1 FROM public.hackathons h WHERE h.id=hackathon_announcements.hackathon_id AND h.organizer_id=auth.uid())
)

CREATE POLICY hackathon_announcements_delete ON public.hackathon_announcements FOR DELETE TO authenticated USING(
 EXISTS(SELECT 1 FROM public.hackathons h WHERE h.id=hackathon_announcements.hackathon_id AND h.organizer_id=auth.uid())
)

create policy registrations_read on public.hackathon_registrations for select to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1 from public.hackathons h
      where h.id = hackathon_id and h.organizer_id = auth.uid()
    )
  )

CREATE POLICY hackathon_posts_insert ON public.hackathon_posts
  FOR INSERT TO authenticated
  WITH CHECK (
    user_id = auth.uid() AND (
      EXISTS (
        SELECT 1 FROM public.hackathons h
        WHERE h.id = hackathon_id AND h.organizer_id = auth.uid()
      ) OR EXISTS (
        SELECT 1 FROM public.hackathon_registrations hr
        WHERE hr.hackathon_id = hackathon_id AND hr.user_id = auth.uid()
      )
    )
  )

CREATE POLICY hackathon_announcements_read ON public.hackathon_announcements
FOR SELECT TO authenticated USING (
  public.can_access_partner_event(hackathon_announcements.hackathon_id)
  OR ((SELECT public.has_verified_event_identity()) AND EXISTS (
    SELECT 1 FROM public.hackathon_registrations AS hr
    WHERE hr.hackathon_id = hackathon_announcements.hackathon_id
      AND hr.user_id = (SELECT auth.uid())
  ))
)

CREATE POLICY hackathon_announcements_update ON public.hackathon_announcements
FOR UPDATE TO authenticated USING (
  public.can_access_partner_event(hackathon_announcements.hackathon_id)
  AND (public.has_partner_admin_access() OR EXISTS (
    SELECT 1 FROM public.hackathons AS h WHERE h.id = hackathon_announcements.hackathon_id
      AND h.type = 'native' AND h.organizer_id = (SELECT auth.uid())
  ))
) WITH CHECK (
  public.can_access_partner_event(hackathon_announcements.hackathon_id)
  AND (public.has_partner_admin_access() OR EXISTS (
    SELECT 1 FROM public.hackathons AS h WHERE h.id = hackathon_announcements.hackathon_id
      AND h.type = 'native' AND h.organizer_id = (SELECT auth.uid())
  ))
)

CREATE POLICY hackathon_announcements_delete ON public.hackathon_announcements
FOR DELETE TO authenticated USING (
  public.can_access_partner_event(hackathon_announcements.hackathon_id)
  AND (public.has_partner_admin_access() OR EXISTS (
    SELECT 1 FROM public.hackathons AS h WHERE h.id = hackathon_announcements.hackathon_id
      AND h.type = 'native' AND h.organizer_id = (SELECT auth.uid())
  ))
)
